"""wp81 item 5: the jungle temple's lever puzzle, Kiln (K) against vanilla (V). Seed 78 (sv.sh): the temple near TEMPLE_AT (default -304,-1232, found by wp78) is generated by
both servers. The levers, sticky pistons and chests inside it are found with `fill ... replace` counts (every count is undone by cloning the temple back from a copy kept above it),
then the levers are pulled in every order of a short list (`setblock` of the lever with powered=true: the neighbour updates are the same ones a click sends) and the pistons'
`extended` states and the chests' reachability (is the block in front of the chest air or a piston head?) are read after every pull, a few ticks later. Output: one line per step,
K and V side by side, and a summary of the differences.
usage: jungle81.py [X Z]    needs both servers with SEED=78 and the bot W0"""
import re, sys, time, itertools
from lk import *

X = int(sys.argv[1]) if len(sys.argv) > 1 else -304
Z = int(sys.argv[2]) if len(sys.argv) > 2 else -1232
O = "execute in minecraft:overworld run "
R = 12


def count(t, box, blk):
    (x1, y1, z1), (x2, y2, z2) = box
    out = ask(t, f"{O}fill {x1} {y1} {z1} {x2} {y2} {z2} minecraft:barrier replace {blk}", wait=0.22)
    m = re.search(r"filled (\d+)|fill\.success\[(\d+)\]", out)
    n = int(m.group(1) or m.group(2)) if m else 0
    return n


def restore(t, box):
    (x1, y1, z1), (x2, y2, z2) = box
    h = y2 - y1 + 1
    w(t, f"{O}clone {x1} {y1 + 100} {z1} {x2} {y2 + 100} {z2} {x1} {y1} {z1}")
    time.sleep(0.25)


def find_all(t, box, blk, limit=40):
    found = []

    def rec(b):
        (x1, y1, z1), (x2, y2, z2) = b
        if count(t, b, blk) == 0:
            return
        restore(t, box)
        if (x1, y1, z1) == (x2, y2, z2):
            found.append((x1, y1, z1))
            return
        # split the longest side
        dx, dy, dz = x2 - x1, y2 - y1, z2 - z1
        if dx >= dy and dx >= dz:
            m = (x1 + x2) // 2
            parts = [((x1, y1, z1), (m, y2, z2)), ((m + 1, y1, z1), (x2, y2, z2))]
        elif dy >= dz:
            m = (y1 + y2) // 2
            parts = [((x1, y1, z1), (x2, m, z2)), ((x1, m + 1, z1), (x2, y2, z2))]
        else:
            m = (z1 + z2) // 2
            parts = [((x1, y1, z1), (x2, y2, m)), ((x1, y1, m + 1), (x2, y2, z2))]
        for p in parts:
            if len(found) < limit:
                rec(p)

    rec(box)
    restore(t, box)
    return sorted(found)


def block_is(t, p, spec):
    return "pass" in ask(t, f"{O}execute if block {p[0]} {p[1]} {p[2]} {spec}", wait=0.12).lower()


for t in "KV":
    if t == "V":
        w(t, "op W0")
    w(t, "gamemode creative W0")
    w(t, "gamerule spawn_mobs false")
    w(t, "gamerule advance_time false")
    w(t, f"{O}forceload add {X - 24} {Z - 24} {X + 24} {Z + 24}")
    w(t, f"{O}tp W0 {X} 120 {Z}")
time.sleep(40)
# the temple's height: the surface at its middle, then 30 blocks down
tops = {}
for t in "KV":
    w(t, f"{O}tp W0 {X} 150 {Z}")
    time.sleep(1)
    for y in range(150, 40, -1):
        if not block_is(t, (X, y, Z), "minecraft:air"):
            tops[t] = y
            break
print("surface at the temple's middle", tops)
top = tops["V"]
box = ((X - R, top - 30, Z - R), (X + R, top + 2, Z + R))
for t in "KV":
    (x1, y1, z1), (x2, y2, z2) = box
    # a copy 100 blocks above (clone 25x33x25 = 20k blocks)
    w(t, f"{O}clone {x1} {y1} {z1} {x2} {y2} {z2} {x1} {y1 + 100} {z1}")
time.sleep(2)
pos = {}
for blk in ("minecraft:lever", "minecraft:sticky_piston", "minecraft:piston", "minecraft:chest", "minecraft:dispenser", "minecraft:tripwire_hook"):
    pos[blk] = {t: find_all(t, box, blk) for t in "KV"}
    same = "SAME" if pos[blk]["K"] == pos[blk]["V"] else "DIFF"
    print(blk, same, len(pos[blk]["K"]), len(pos[blk]["V"]), pos[blk]["V"][:8])
    sys.stdout.flush()
levers = pos["minecraft:lever"]["V"]
sticky = pos["minecraft:sticky_piston"]["V"] + pos["minecraft:piston"]["V"]
chests = pos["minecraft:chest"]["V"]
if not levers:
    sys.exit("no levers found")
# how each lever is mounted
mounts = {}
for p in levers:
    for face in ("floor", "wall", "ceiling"):
        for facing in ("north", "south", "east", "west"):
            if block_is("V", p, f"minecraft:lever[face={face},facing={facing}]"):
                mounts[p] = (face, facing)
print("mounts", mounts)


def state(t):
    s = []
    for p in sticky:
        ext = block_is(t, p, "minecraft:sticky_piston[extended=true]") or block_is(t, p, "minecraft:piston[extended=true]")
        here = ext or block_is(t, p, "minecraft:sticky_piston") or block_is(t, p, "minecraft:piston")
        s.append("E" if ext else "r" if here else "-")
    for p in chests:
        s.append("C" if block_is(t, p, "minecraft:chest") else "-")
    for p in levers:
        s.append("L" if block_is(t, p, "minecraft:lever[powered=true]") else "l")
    return "".join(s)


def pull(t, p, on):
    face, facing = mounts[p]
    w(t, f"{O}setblock {p[0]} {p[1]} {p[2]} minecraft:lever[face={face},facing={facing},powered={'true' if on else 'false'}] replace")


diffs = 0
both("tick freeze")
time.sleep(0.5)
print("pistons/chests/levers legend: E extended piston, r retracted piston, C chest, L lever on")
print("start      K", state("K"), " V", state("V"))
orders = list(itertools.permutations(range(len(levers))))[:6]
for order in orders:
    for p in levers:
        for t in "KV":
            pull(t, p, False)
    step(8)
    for k in order:
        for t in "KV":
            pull(t, levers[k], True)
        step(1)
        step(7)
        sk, sv_ = state("K"), state("V")
        print("order", order, "pulled", k, "K", sk, " V", sv_, "" if sk == sv_ else "  <-- DIFF")
        diffs += sk != sv_
        sys.stdout.flush()
print("steps compared with differences:", diffs)
for t in "KV":
    (x1, y1, z1), (x2, y2, z2) = box
    w(t, f"{O}fill {x1} {y1 + 100} {z1} {x2} {y2 + 100} {z2} minecraft:air")
